module Inner() {
  line A = polar(start: (0, 0), angle: 23, length: 33)
  for i in range(min: 0, max: 0, step: 1) carry edge: path = @A {
    next edge = @A
  }
  export const out: path = @edge
}
module Outer() {
  line Seed = polar(start: (-80, -40), angle: 7, length: 33)
