line Axis = polar(start: (430, -70), angle: 7, length: 33)
line Seed = polar(start: (-80, -40), angle: 7, length: 33)
line Dormant = polar(start: (900, 0), angle: 71, length: 20, enabled: false)
const side: choice(left, right) = right
for i in range(min: 0, max: 1, step: 1) carry edge: path = @Seed carry previous: path = @Seed {
  line Generated = polar(start: (@i * 120, 7), angle: 23 + @i * 11, length: 33)
  move Generated as selected (from: (0, 0), to: (17, -9), angleDeg: 13)
  move Generated as later (from: (0, 0), to: (17, -9), angleDeg: 31)
  next edge = if (true) { if (@i == 0) { @previous } else { @Generated[@i].base } } else { @Dormant }
  next previous = @edge
}
const result: number = lineAngle(@edge.start, @Axis.start)

